using System;
using System.IO;
using System.Reflection;
namespace PZ3D {
 static class ChinesePatchTests {
  static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);}
  public static void Run(){var type=typeof(Engine).Assembly.GetType("PZ3D.ChinesePatch");Check(type!=null,"Chinese patch configuration manager exists");var root=Path.Combine(Path.GetTempPath(),"orange-cn-"+Guid.NewGuid().ToString("N"));var e=new Engine(Path.Combine(root,"game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true);Directory.CreateDirectory(e.Game);Directory.CreateDirectory(Path.GetDirectoryName(e.Mods));File.WriteAllText(e.Config,"{\"vmArgs\":[\"-agentlib:zbNative\"]}");File.WriteAllText(Path.Combine(e.Game,"ZombieBuddy.jar"),"fixture");File.WriteAllText(Path.Combine(e.Game,"zbNative.dll"),"fixture");string original="VERSION = 1,\nmods\n{\n mod = ZombieBuddy,\n mod = Viewpoint,\n mod = Other,\n}\nmaps\n{\n map = OtherMap,\n}\n";File.WriteAllText(e.Mods,original);string source=Path.Combine(root,"source");var store=Activator.CreateInstance(type);bool rejected=false;try{type.GetMethod("Enable").Invoke(store,new object[]{e,source});}catch(TargetInvocationException){rejected=true;}Check(rejected&&File.ReadAllText(e.Mods)==original,"missing Chinese files refuse install without mutating mods");
   string id=(string)type.GetField("Id").GetValue(null);string folder=Path.Combine(source,"mods",id);Directory.CreateDirectory(Path.Combine(folder,"common"));Directory.CreateDirectory(Path.Combine(folder,"42","media","java","client"));File.WriteAllText(Path.Combine(folder,"common","mod.info"),"id="+id+"\njavaJarFile=media/java/client/LaoYuTranslationJava.jar\njavaPkgName=laoyu.javacn\n");File.WriteAllText(Path.Combine(folder,"42","media","java","client","LaoYuTranslationJava.jar"),"fixture");type.GetMethod("Enable").Invoke(store,new object[]{e,source});string enabled=File.ReadAllText(e.Mods);Check(enabled.Contains("mod = "+id+",")&&enabled.Contains("mod = Other,")&&enabled.Contains("map = OtherMap,"),"Chinese install preserves other mods and maps");type.GetMethod("Enable").Invoke(store,new object[]{e,source});Check(File.ReadAllText(e.Mods)==enabled,"Chinese install is idempotent");type.GetMethod("Disable").Invoke(store,new object[]{e});Check(!File.ReadAllText(e.Mods).Contains("mod = "+id+",")&&File.ReadAllText(e.Mods).Contains("mod = Viewpoint,")&&File.ReadAllText(e.Mods).Contains("mod = Other,"),"Chinese uninstall preserves base and unrelated mods");
   var policy=typeof(InstallWorkflow).GetMethod("KeepModels");Check(policy!=null,"install and update preserve unselected installed model component");File.WriteAllText(e.Mods,original.Replace(" mod = Other,"," mod = PZVoxelStudioViewpoint,\n mod = Other,"));Check((bool)policy.Invoke(null,new object[]{e,false}),"installing only Chinese does not disable existing models");File.WriteAllText(e.Mods,original);Check(!(bool)policy.Invoke(null,new object[]{e,false})&&(bool)policy.Invoke(null,new object[]{e,true}),"model opt-out does not enable absent models, explicit selection enables them");
   var sourceMethod=typeof(InstallWorkflow).GetMethod("Source");Check(sourceMethod!=null,"optional components resolve actual Steam returned library folders");Directory.CreateDirectory(e.Data);File.WriteAllText(Path.Combine(e.Data,"workshop-paths.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new System.Collections.Generic.Dictionary<string,string>{{"3810637496",source}}));Check((string)sourceMethod.Invoke(null,new object[]{e,3810637496UL})==source,"Chinese install uses cached actual workshop folder instead of creator library");
   File.WriteAllText(e.Mods,"unrecognized format");rejected=false;try{type.GetMethod("Enable").Invoke(store,new object[]{e,source});}catch(TargetInvocationException){rejected=true;}Check(rejected&&File.ReadAllText(e.Mods)=="unrecognized format","unrecognized mod list is not overwritten");
  }
 }
}
